UPDATE "Creator" SET "bio" = 'Pete Rojwongsuriya is a Bangkok-born solo traveller who has spent 13+ years on the road and visited 103+ countries. His guides lean toward budget backpacking, mountains and off-the-beaten-path places, and he pays for his own trips with no sponsorships.' WHERE "handle" = 'bucketlistly';
UPDATE "Creator" SET "bio" = 'Fora is a network of travel advisors who plan and book trips for their clients. Its advisors write these destination guides, often with boutique and luxury stays.' WHERE "handle" = 'foratravel';
UPDATE "Creator" SET "bio" = 'Jon Miksis is a Boston-based travel writer who started Global Viewpoint in 2017 and has visited 70+ countries. He calls his style "value travel": spending smart, with the odd luxury stay. His work has appeared in Forbes, HuffPost and the Boston Globe.' WHERE "handle" = 'globalviewpoint';
UPDATE "Creator" SET "bio" = 'Mark Wiens is an American food traveller who has lived in Bangkok since 2009. Eating Thai Food is his guide to Thai dishes, street food and where to eat them.' WHERE "handle" = 'markwiens';
UPDATE "Creator" SET "bio" = 'Rachel is a writer and travel consultant based in Southern California who grew up on Oahu. Her blog covers career-friendly travel, remote-work trips and, lately, a career-break road trip around Australia.' WHERE "handle" = 'racheloffduty';
UPDATE "Creator" SET "bio" = 'Salt in our Hair is the travel blog of Hannah and Nick, with detailed itineraries and photography from their trips around the world.' WHERE "handle" = 'saltinourhair';
UPDATE "Creator" SET "bio" = 'Founded by Will Hatton in 2013, The Broke Backpacker is a team of writers covering honest, budget, off-the-beaten-path backpacking in 90+ countries.' WHERE "handle" = 'thebrokebackpacker';
UPDATE "Creator" SET "bio" = 'Dave and Deb have run The Planet D since 2007 and travelled to 130+ countries on all 7 continents. They focus on adventure travel, from cycling across Africa to Antarctica, and have twice won Lowell Thomas Travel Blog of the Year.' WHERE "handle" = 'theplanetd';
UPDATE "Creator" SET "bio" = 'Michael Turtle is an Australian former TV and radio reporter who now travels full time with no fixed home. He focuses on UNESCO World Heritage sites, culture and history, and on avoiding the crowds.' WHERE "handle" = 'timetravelturtle';
UPDATE "Creator" SET "bio" = 'Evie is from Cyprus and lives in London. She started her blog after a gap year to share travel photos, tips and food finds.' WHERE "handle" = 'vamosbitchachos';
